import{_ as e,c as a,a2 as p,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百一十五章 如何生到富贵舒服的地方？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/115第一百一十五章 如何生到富贵舒服的地方.md","filePath":"meditation/巴利文大藏经/115第一百一十五章 如何生到富贵舒服的地方.md"}'),o={name:"meditation/巴利文大藏经/115第一百一十五章 如何生到富贵舒服的地方.md"};function r(n,t,i,s,d,c){return _(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百一十五章-如何生到富贵舒服的地方" tabindex="-1">第一百一十五章 如何生到富贵舒服的地方？ <a class="header-anchor" href="#第一百一十五章-如何生到富贵舒服的地方" aria-label="Permalink to &quot;第一百一十五章 如何生到富贵舒服的地方？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部14相应13经/砖屋经(界相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在那低葛的砖屋中。有一天，佛陀对出家弟子们说：“弟子们，以界（界解释，见第一百零三章）为前提条件就会生起念想、见解、觉悟。”</p><p>佛陀这样说的时候，迦旃延尊者就对佛陀说：“世尊，那些没有证悟无上正等正觉的人，他们的见解是因为什么而生起来的呢？”</p><p>佛陀说：“迦旃延！他们的见解是因为无限巨大的界生起来的，这个界就是无明界，什么是无明界呢？就是没有真实智慧的地方，沉迷在各种欲望之中，被各种烦恼和痛苦束缚捆绑不得解脱的地方，这就是无明界。</p><p>迦旃延！以下界为前提条件，以出生、生活在下界之中为前提条件就会生起低等、恶劣的念想，就会生起低等、恶劣的见解，就会生起低等、恶劣的觉悟，就会生起低等、恶劣的思想，就会生起低等、恶劣的追求，就会生起低等、恶劣的愿望，就会生起低等、恶劣品质的人，就会生起低等、恶劣的言语，下界是什么意思呢？下界就是痛苦的地方，受苦的地方，生存恶劣的地方，贫贱的地方，地狱道，饿鬼道，畜生道。这些在下界中的人，由于他们被告知、教导、安立、建立、开显、解释、阐明的见解是低等、恶劣的，他们的内心就会充满邪见，他们就会没有正确的智慧，他们的行为、言语、念想就会因为错误的见解而做出很多伤害别人的恶事，如来就说他们死后，将会投生到痛苦的地方，投生到受苦的地方，投生到贫贱的地方，甚至于投生到地狱、饿鬼、畜生三恶道受苦。</p><p>迦旃延！以中界为前提条件，以出生、生活在中界之中为前提条件就会生起中等、普通的念想，就会生起中等、普通的见解，就会生起中等、普通的觉悟，就会生起中等、普通的思想，就会生起中等、普通的追求，就会生起中等、普通的愿望，就会生起中等、普通品质的人，就会生起中等、普通的言语，中界是什么意思呢？中界就是寻常的地方，普通的地方，生存条件一般的地方，不贫贱也不富贵的地方，平凡的地方。这些在中界中的人，由于他们被告知、教导、安立、建立、开显、解释、阐明的见解是中等、普通的，他们的内心就会充满平凡、普通的见解，他们就会没有正确的智慧，他们的行为、言语、念想就会因为平凡、普通的见解而无所作为，他们有时也会做出一些伤害别人的恶事，如来就说他们死后，将会投生到平凡、普通的地方，投生到不贫贱也不富贵的地方。</p><p>迦旃延！以胜妙界为前提条件，以出生、生活在胜妙界之中为前提条件就会生起上等、高明的念想，就会生起上等、高明的见解，就会生起上等、高明的觉悟，就会生起上等、高明的思想，就会生起上等、高明的追求，就会生起上等、高明的愿望，就会生起上等、高明品质的人，就会生起上等、高明的言语，胜妙界是什么意思呢？胜妙界就是高贵的地方，快乐的地方，生存舒适的地方，富贵的地方，各种阶层的天界。这些在胜妙界中的人，由于他们被告知、教导、安立、建立、开显、解释、阐明的见解是上等、高明的，他们的内心就会具足正见，他们就会有正确的智慧，他们的行为、言语、念想就会因为正确的见解而做出很多帮助、保护别人的善事，如来就说他们死后，将会投生到高贵的地方，投生到快乐舒适的地方，投生到富贵的地方，甚至于投生到各种阶层的天界中享福。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',10)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
